def test_json_with_charset_utf16() -> None:
    """JSON with UTF-16 charset should be rejected (UTF-8 only)."""
    base = os.environ.get("SUT_URL", "http://127.0.0.1:8000")
    url = f"{base}/fixtures/13_json_with_charset_utf16/data"
    _headers = {
        "Content-Type": "application/json; charset=utf-16",
    }
    _headers.setdefault("Content-Type", "application/json")
    _body = json.dumps({"value": "test"}).encode()
    _req = urllib.request.Request(url, data=_body, headers=_headers, method="POST")  # noqa: S310

    class _NoRedirect(urllib.request.HTTPRedirectHandler):
        def redirect_request(self, *args, **kwargs):  # noqa: ANN002, ANN003, ANN202, ARG002
            return None

    _opener = urllib.request.build_opener(_NoRedirect())
    try:
        response = _opener.open(_req)
        status_code = response.status
        resp_body = response.read()
        resp_headers = dict(response.headers)
    except urllib.error.HTTPError as _exc:
        status_code = _exc.code
        resp_body = _exc.read()
        resp_headers = dict(_exc.headers)  # noqa: F841
    assert status_code == 415
    data = json.loads(resp_body)
    assert data == {
        "detail": "Unsupported charset 'utf-16' for JSON. Only UTF-8 is supported.",
        "status": 415,
        "title": "Unsupported Charset",
        "type": "https://spikard.dev/errors/unsupported-charset",
    }


